'use strict';
window.Campaigns=(()=>{
 let session=null,table=null,members=[],topics=[],characters=[],serial=0,booted=false;
 const L=(en,es)=>Pack2.language==='es'?es:en;
 const H=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const date=s=>new Intl.DateTimeFormat(Pack2.language==='es'?'es-PA':'en-US',{dateStyle:'medium',timeStyle:'short',timeZone:'America/Panama'}).format(new Date(s));
 const base=c=>'/api/campaigns/'+c;
 const errors={sign_in_required:['Sign in to continue.','Inicia sesión para continuar.'],campaign_not_found:['This campaign is unavailable to your account.','Esta campaña no está disponible para tu cuenta.'],topic_not_found:['This note is private or no longer available.','Esta nota es privada o ya no está disponible.'],character_not_found:['This character is unavailable.','Este personaje no está disponible.'],dm_only:['Only the DM can do that.','Solo el DM puede hacer eso.'],author_only:['You cannot edit this item.','No puedes editar este contenido.'],invalid_fields:['Check the fields and their lengths.','Revisa los campos y sus límites.'],invalid_character:['This character file is not compatible.','Este archivo de personaje no es compatible.'],invalid_entries:['Some entries are outside this atlas.','Algunas entradas no pertenecen a este atlas.'],invalid_json:['This file could not be read.','No se pudo leer este archivo.'],edit_conflict:['Someone saved a newer version. Your draft remains below; copy it before reloading the current version.','Alguien guardó una versión más reciente. Tu borrador sigue aquí; cópialo antes de recargar la versión actual.'],invitation_invalid:['This invitation expired or was revoked. Ask the DM for a new link.','Esta invitación venció o fue revocada. Pide al DM un enlace nuevo.'],invitation_full:['This invitation has no places left.','Esta invitación ya no tiene cupos.'],campaign_archived:['This campaign is archived. Its DM can reopen it.','Esta campaña está archivada. Su DM puede reabrirla.'],topic_archived:['This topic is archived. Restore it to reply.','Este tema está archivado. Restáuralo para responder.'],unsupported_file:['Use a PNG, JPEG, WebP image, or a PDF attachment.','Usa una imagen PNG, JPEG o WebP, o un PDF como adjunto.'],file_too_large:['Images can be up to 5 MB; PDFs up to 10 MB.','Las imágenes admiten hasta 5 MB; los PDF, hasta 10 MB.'],storage_unavailable:['Campaign storage is unavailable. Try again shortly.','El guardado de campañas no está disponible. Intenta de nuevo en un momento.'],files_unavailable:['File storage is unavailable.','El almacenamiento de archivos no está disponible.'],server_error:['The change could not be saved. Your draft is still here.','No se pudo guardar el cambio. Tu borrador sigue aquí.'],invalid_origin:['Reload the page and try again.','Recarga la página e intenta de nuevo.'],owner_cannot_leave:['The campaign owner remains its DM.','El propietario de la campaña conserva el rol de DM.'],campaign_limit:['Your account reached the campaign limit.','Tu cuenta llegó al límite de campañas.'],file_limit:['This campaign reached its attachment limit.','Esta campaña llegó al límite de adjuntos.']};
 const errorText=e=>{const pair=errors[e.code];return pair?L(...pair):L('The request could not be completed. Please try again.','No se pudo completar la solicitud. Intenta de nuevo.')};
 async function api(path,method='GET',body){const routeAtStart=location.hash;let r;try{r=await fetch(path,{method,credentials:'same-origin',headers:{'x-kalvatar-request':'campaign-v1',...(body!==undefined?{'content-type':'application/json'}:{})},body:body===undefined?undefined:JSON.stringify(body)})}catch{const e=Error();e.code='network';throw e}let data;try{data=await r.json()}catch{data={error:'server_error'}}if(routeAtStart!==location.hash){const e=Error();e.code='route_changed';throw e}if(!r.ok){const e=Error(data.error);Object.assign(e,{code:data.error,status:r.status,...data});throw e}return data}
 function download(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 function status(el,message,bad=false){if(!el)return;el.textContent=message;el.classList.toggle('bad',bad)}
 async function submit(form,fn){const buttons=form.querySelectorAll('button[type="submit"],button:not([type])');buttons.forEach(b=>b.disabled=true);try{await fn()}catch(e){status(form.querySelector('[data-form-status]'),errorText(e),true)}finally{buttons.forEach(b=>b.disabled=false)}}
 const formStatus=()=>'<p class="campaign-status" data-form-status role="status" aria-live="polite"></p>';
 const isDm=()=>table?.role==='dm';
 Object.assign(errors,{invalid_music_url:['Use an HTTPS link from Spotify, YouTube, Apple Music, SoundCloud or Bandcamp.','Usa un enlace HTTPS de Spotify, YouTube, Apple Music, SoundCloud o Bandcamp.'],music_limit:['This campaign reached its music-link limit.','Esta campaña llegó al límite de enlaces de música.']});
 const tags={shared:()=>L('Shared with the table','Toda la mesa'),private:()=>L('Only you','Solo tú'),'player-dm':()=>L('You and the DM','Tú y el DM'),dm:()=>L('DM only','Solo DM')};
 const tag=v=>tags[v]?.()||v;
 const makeLink=(entry,label)=>Pack2.canRead(entry)&&byId[entry]?`<a class="wiki-link" href="#entry/${H(entry)}">${H(label||byId[entry].title)}</a>`:H(label||byId[entry]?.title||entry);
 function rich(body){
  const names=new Map(entries.flatMap(e=>[e.title,...(e.aliases||[])].map(n=>[fold(n).replace(/^the /,''),e.id])));let last=0,out='';const re=/\[\[([^\]\n]{1,200})\]\]|https?:\/\/[^\s<>]+/g;
  for(const m of body.matchAll(re)){out+=H(body.slice(last,m.index));if(m[1]){const [key,label]=m[1].split('|');const entry=key.startsWith('entry:')?key.slice(6):names.get(fold(key).replace(/^the /,''));out+=entry?makeLink(entry,label||byId[entry]?.title||key):H(label||key)}else{let url=m[0];try{const u=new URL(url);out+=['https:','http:'].includes(u.protocol)?`<a class="wiki-link" target="_blank" rel="noopener noreferrer" href="${H(u.href)}">${H(url)}</a>`:H(url)}catch{out+=H(url)}}last=m.index+m[0].length}
  return (out+H(body.slice(last))).replace(/\n/g,'<br>');
 }
 function page(title,intro,body){setNavigation('tables');document.title=title+' | Kalvatar';$('#breadcrumb').innerHTML=`<a href="#tables">${L('My campaigns','Mis campañas')}</a><span>/</span>${H(title)}`;$('#content').innerHTML=`<div class="content-wrap campaign-space"><header class="campaign-page-header"><p class="eyebrow">KALVATAR / ${L('THE CAMPAIGN JOURNALS','LAS BITÁCORAS DE CAMPAÑA')}</p><h1>${H(title)}</h1><p>${H(intro)}</p></header>${body}</div>`;window.scrollTo({top:0,behavior:'instant'})}
 function loading(){page(L('Opening the journal…','Abriendo la bitácora…'),L('Finding your table.','Buscando tu mesa.'),'<div class="campaign-loading" role="status">✦</div>')}
 function failPage(e){page(L('The journal is closed.','La bitácora está cerrada.'),errorText(e),`<a class="button" href="#tables">${L('Back to my campaigns','Volver a mis campañas')} →</a>`)}
 async function getSession(){session=await api('/api/session?return_to='+encodeURIComponent('/'+location.hash));if(Pack2.campaign?.server&&Pack2.campaign.user_id!==session.user?.id)Pack2.clearServer();return session}
 function signIn(){page(L('A place for your table.','Un lugar para tu mesa.'),L('Keep your characters, private notes, and shared adventures together.','Reúne tus personajes, notas privadas y aventuras compartidas.'),`<div class="campaign-welcome"><div class="campaign-welcome-mark" aria-hidden="true">${icon('compass')}</div><div><h2>${L('Sign in with ChatGPT','Inicia sesión con ChatGPT')}</h2><p>${L('Use your existing account. Your campaigns are saved online and follow you between devices.','Usa tu cuenta habitual. Tus campañas se guardan en línea y te acompañan entre dispositivos.')}</p><a class="button" target="_top" href="${H(session.sign_in)}">${L('Sign in to my campaigns','Entrar a mis campañas')} ↗</a><p class="campaign-fine">${L('The public atlas is always open. Private notes are visible only to their author; sharing with the DM is your choice.','El atlas público sigue abierto. Las notas privadas solo las ve su autor; compartirlas con el DM es tu decisión.')}</p></div></div><a class="text-link" href="#browse">${L('Return to the atlas','Volver al atlas')} →</a>`)}
 async function signed(){await getSession();if(!session.user){signIn();return false}if(!session.storage_ready){const e=Error();e.code='storage_unavailable';throw e}return true}
 function account(){return `<div class="campaign-account"><span>${H(session.user.name)}</span><a href="#account">${L('My profile','Mi perfil')}</a><a data-signout target="_top" href="${H(session.sign_out)}">${L('Sign out','Cerrar sesión')}</a></div>`}
 const presets={goldwind:['kalvatar','goldwind','merla-ciel-tealeaf','mako-rodis-patches','coralie-calloway','heartland','humans','travel','calendar','coinage','hunters','companions','hospitality'],storm:['robin-faust','crys','araye-moss','kalvatar','travel','calendar','coinage','king-tide','hunters','companions','hospitality','sea-pacts']};
 async function hub(){if(!await signed())return;const {campaigns}=await api('/api/campaigns');page(L('My campaigns','Mis campañas'),L('Every table keeps its own chart.','Cada mesa guarda su propia carta.'),account()+`<p><a class="button" href="#characters">${L('My characters · no invitation needed','Mis personajes · sin invitación')} →</a></p><div class="campaign-toolbar"><h2>${L('Your tables','Tus mesas')}</h2><button class="button" id="new-table-toggle">${L('Create a campaign','Crear campaña')} +</button></div><section id="new-table-panel" hidden class="campaign-panel"><h2>${L('Set a place at the table.','Haz un lugar en la mesa.')}</h2><form id="new-table"><label>${L('Campaign name','Nombre de la campaña')}<input name="name" required maxlength="100" placeholder="The Table of Twelve"></label><label>${L('A few words for the invitation','Unas palabras para la invitación')}<textarea name="description" rows="3" maxlength="3000"></textarea></label><label>${L('First discoveries','Primeros descubrimientos')}<select name="preset"><option value="goldwind">${L('Begin in Goldwind','Comenzar en Goldwind')}</option><option value="storm">The Year of the Storm</option><option value="empty">${L('An uncharted beginning','Un comienzo sin cartografiar')}</option>${Pack2.campaign&&!Pack2.campaign.server?`<option value="legacy">${L('Use my current discovery list','Usar mi lista actual de descubrimientos')}</option>`:''}</select></label>${formStatus()}<button class="button" type="submit">${L('Create my table','Crear mi mesa')} →</button></form></section><div class="campaign-table-grid">${campaigns.map(c=>`<a class="campaign-table-card" href="#table/${c.id}/board"><span class="eyebrow">${c.role==='dm'?'DM':L('PLAYER','JUGADOR')}${c.archived?' · '+L('ARCHIVED','ARCHIVADA'):''}</span><h2>${H(c.name)}</h2><p>${H(c.description||L('Another shore, another story.','Otra orilla, otra historia.'))}</p><footer><span>${c.member_count} ${L('at the table','en la mesa')}</span><span>↗</span></footer></a>`).join('')||`<div class="campaign-empty"><h2>${L('The first page is yours.','La primera página es tuya.')}</h2><p>${L('Create a campaign as its DM, or open the invitation your DM shared.','Crea una campaña como DM o abre la invitación que compartió tu DM.')}</p></div>`}</div>`);$('#new-table-toggle').onclick=()=>{$('#new-table-panel').hidden=!$('#new-table-panel').hidden;if(!$('#new-table-panel').hidden)$('#new-table input').focus()};$('#new-table').onsubmit=e=>{e.preventDefault();submit(e.currentTarget,async()=>{const f=new FormData(e.target),preset=f.get('preset'),unlocked=preset==='legacy'?Pack2.campaign.unlocked:preset==='empty'?[]:presets[preset];const result=await api('/api/campaigns','POST',{name:f.get('name'),description:f.get('description'),unlocked});location.hash='table/'+result.id+'/board'})}}
 async function openTable(c){const result=await api(base(c));table={...result.campaign,featured_music:result.featured_music};members=result.members;Pack2.activateServer({...table,user_id:session.user.id});return table}
 function tableNav(tab){return `<div class="campaign-table-heading"><a href="#tables" class="text-link">← ${L('My campaigns','Mis campañas')}</a><button class="text-link" type="button" data-leave-reading>${L('Full atlas','Atlas completo')} ↗</button><span class="campaign-role">${isDm()?'DM':L('PLAYER','JUGADOR')}${table.archived?' · '+L('ARCHIVED','ARCHIVADA'):''}</span></div><div class="campaign-title"><h2>${H(table.name)}</h2><p>${H(table.description)}</p></div><nav class="campaign-tabs" aria-label="${L('Campaign sections','Secciones de campaña')}">${[['board',L('Table forum','Foro de la mesa')],['notes',L('My notes','Mis notas')],['characters',L('Characters','Personajes')],['music',L('Soundtrack','Banda sonora')],['discoveries',L('Discoveries','Descubrimientos')],...(isDm()?[['guide','Guía de campaña'],['dm',L('DM notebook','Cuaderno del DM')],['members',L('Members & invitations','Miembros e invitaciones')],['settings',L('Settings','Ajustes')]]:[])].map(([id,title])=>`<a href="#table/${table.id}/${id}" ${id===tab?'aria-current="page"':''}>${title}</a>`).join('')}</nav>${table.featured_music?`<div class="campaign-score"><span aria-hidden="true">♫</span><div><span class="eyebrow">${L('FEATURED BY THE DM','DESTACADA POR EL DM')}</span><a target="_blank" rel="noopener noreferrer" href="${H(table.featured_music.url)}">${H(table.featured_music.title)} ↗</a><small>${H(table.featured_music.provider)}${table.featured_music.scene?' · '+H(table.featured_music.scene):''}</small></div></div>`:''}`}
 function tablePage(title,intro,body,tab){page(title,intro,tableNav(tab)+body)}
 const topicCard=t=>`<a class="forum-topic ${t.archived?'archived':''}" href="#thread/${table.id}/${t.id}"><div><span class="eyebrow">${t.pinned?'✦ '+L('PINNED','FIJADO')+' · ':''}${H(tag(t.visibility))}${t.session?' · '+H(t.session):''}</span><h3>${H(t.title)}</h3><p>${H(t.body.replace(/\[\[(?:entry:)?([^|\]]+)(?:\|([^\]]+))?\]\]/g,(_,id,label)=>label||byId[id]?.title||id).slice(0,190))}${t.body.length>190?'…':''}</p><span class="forum-topic-by">${H(t.author_name)} · ${date(t.updated_at)}</span></div><span class="forum-topic-replies">${t.reply_count||0}<small>${Number(t.reply_count)===1?L('reply','respuesta'):L('replies','respuestas')}</small></span></a>`;
 async function topicList(tab){topics=(await api(base(table.id)+'/topics')).topics;const title=tab==='board'?L('The table forum','El foro de la mesa'):tab==='dm'?L('The DM notebook','El cuaderno del DM'):L('My notes','Mis notas');const intro=tab==='board'?L('Open a topic, compare clues, and keep the story together. Everyone at the table can reply.','Abre un tema, compara pistas y reúne la historia. Todos en la mesa pueden responder.'):tab==='dm'?L('Your DM notes and the notes players chose to share with you.','Tus notas de DM y las notas que los jugadores eligieron compartir contigo.'):L('Private by default. Share an individual note with the DM whenever you choose.','Privadas por defecto. Comparte una nota concreta con el DM cuando tú decidas.');tablePage(title,intro,`<div class="campaign-toolbar"><label class="campaign-search-label">${L('Find a note or topic','Busca una nota o un tema')}<input id="forum-search" type="search"></label><button class="text-link" id="refresh-forum">${L('Refresh','Actualizar')} ↻</button><a class="button" href="#table/${table.id}/${tab==='board'?'new-thread':tab==='dm'?'new-dm':'new-note'}">${tab==='board'?L('New topic','Nuevo tema'):L('New note','Nueva nota')} +</a></div><label class="campaign-check-small"><input id="show-archived" type="checkbox">${L('Show archived','Mostrar archivados')}</label><div id="forum-topics"></div>`,tab);const draw=()=>{const q=fold($('#forum-search').value);const filtered=topics.filter(t=>(tab==='board'?t.kind==='thread':tab==='dm'?t.visibility==='dm'||(t.visibility==='player-dm'&&t.author_id!==session.user.id):t.kind==='note'&&t.author_id===session.user.id&&t.visibility!=='dm')&&($('#show-archived').checked||!t.archived)&&fold(t.title+' '+t.body+' '+t.author_name+' '+t.session).includes(q));$('#forum-topics').innerHTML=filtered.map(topicCard).join('')||`<div class="campaign-empty"><p>${L('No pages here yet. Start with a first note.','Todavía no hay páginas aquí. Empieza con una primera nota.')}</p></div>`};$('#forum-search').oninput=draw;$('#show-archived').onchange=draw;$('#refresh-forum').onclick=()=>refresh();draw()}
 const field=(name,label,value='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${H(value)}" ${extra}></label>`;
 function mentionEditor(name,value,max=50000){return `<div class="mention-editor"><label>${L('Text','Texto')}<textarea name="${name}" rows="10" maxlength="${max}" data-mentions>${H(value||'')}</textarea></label><div class="mention-suggestions" role="listbox" hidden></div><p class="campaign-fine">${L('Type [[ to link a discovered atlas entry. Web addresses become links too.','Escribe [[ para enlazar una entrada descubierta del atlas. Las direcciones web también se convierten en enlaces.')}</p></div>`}
 function mentions(root){root.querySelectorAll('[data-mentions]').forEach(area=>{const wrap=area.closest('.mention-editor'),box=wrap.querySelector('.mention-suggestions');let chosen=0,list=[],match=null;const draw=()=>{const left=area.value.slice(0,area.selectionStart);match=/\[\[([^\]\n]{0,80})$/.exec(left);if(!match){box.hidden=true;return}const q=fold(match[1]);list=entries.filter(e=>Pack2.canRead(e.id)&&fold(e.title+' '+(e.aliases||[]).join(' ')).includes(q)).sort((a,b)=>a.title.localeCompare(b.title)).slice(0,7);chosen=0;show()};const show=()=>{box.hidden=!list.length;box.innerHTML=list.map((e,i)=>`<button type="button" role="option" aria-selected="${i===chosen}" data-mention-id="${e.id}">${H(e.title)}<small>${H(e.region)}</small></button>`).join('')};const insert=id=>{if(!match)return;const start=area.selectionStart-match[0].length;area.setRangeText('[[entry:'+id+'|'+byId[id].title+']]',start,area.selectionStart,'end');area.focus();box.hidden=true;area.dispatchEvent(new Event('input',{bubbles:true}))};area.addEventListener('input',draw);area.addEventListener('keydown',e=>{if(box.hidden)return;if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();chosen=(chosen+(e.key==='ArrowDown'?1:list.length-1))%list.length;show()}if(e.key==='Enter'){e.preventDefault();insert(list[chosen].id)}if(e.key==='Escape'){e.preventDefault();box.hidden=true}});box.onclick=e=>{const b=e.target.closest('[data-mention-id]');if(b)insert(b.dataset.mentionId)}})}
 const draftKey=(kind,id)=>'kalvatar-cloud-draft-v1:'+session.user.id+':'+table.id+':'+kind+':'+id;
 function drafts(form,key,sourceVersion){let saved;try{saved=JSON.parse(localStorage.getItem(key)||'null')}catch{}if(saved&&saved.sourceVersion===sourceVersion){for(const [name,value]of Object.entries(saved.fields||{})){const el=form.elements.namedItem(name);if(el&&el.type!=='checkbox')el.value=value}status(form.querySelector('[data-form-status]'),L('An unfinished draft was restored from this browser.','Se recuperó un borrador pendiente de este navegador.'))}form.addEventListener('input',()=>{const fields=Object.fromEntries(new FormData(form));try{localStorage.setItem(key,JSON.stringify({fields,sourceVersion,at:Date.now()}))}catch{}})}
 async function editor(kind,existing=null,seed=''){
  const thread=existing?existing.kind==='thread':kind==='new-thread',vis=existing?.visibility||(kind==='new-dm'?'dm':thread?'shared':'private');
  const title=existing?L('Edit this page','Editar esta página'):thread?L('Start a topic','Abre un tema'):L('A new note','Una nota nueva');
  tablePage(title,thread?L('Everyone at the table can read and reply.','Todos en la mesa pueden leer y responder.'):L('Choose who can read this note.','Elige quién puede leer esta nota.'),`<form id="topic-editor" class="campaign-panel">${field('title',L('Title','Título'),existing?.title||'', 'text','required maxlength="160"')}${field('session',L('Session or chapter (optional)','Sesión o capítulo (opcional)'),existing?.session||'','text','maxlength="80"')}${mentionEditor('body',existing?.body||seed)}${thread?`<p class="visibility-badge">${H(tag('shared'))}</p>`:`<label>${L('Who can read it?','¿Quién puede leerla?')}<select name="visibility"><option value="private" ${vis==='private'?'selected':''}>${tag('private')}</option><option value="player-dm" ${vis==='player-dm'?'selected':''}>${tag('player-dm')}</option>${isDm()?`<option value="dm" ${vis==='dm'?'selected':''}>${tag('dm')}</option>`:''}</select></label>`}${isDm()&&thread?`<label class="campaign-check-small"><input name="pinned" type="checkbox" ${existing?.pinned?'checked':''}>${L('Pin for the table','Fijar para la mesa')}</label>`:''}${formStatus()}<div class="campaign-actions"><button class="button" type="submit">${L('Save online','Guardar en línea')} →</button><a class="text-link" href="${existing?'#thread/'+table.id+'/'+existing.id:'#table/'+table.id+'/'+(thread?'board':vis==='dm'?'dm':'notes')}">${L('Back','Volver')}</a></div></form>`,thread?'board':vis==='dm'?'dm':'notes');const form=$('#topic-editor'),key=draftKey('topic',existing?.id||kind);drafts(form,key,existing?.version||0);mentions(form);form.onsubmit=e=>{e.preventDefault();submit(form,async()=>{const f=new FormData(form);const body={title:f.get('title'),body:f.get('body'),session:f.get('session'),kind:thread?'thread':'note',visibility:thread?'shared':f.get('visibility')};if(isDm()&&thread)body.pinned=f.has('pinned')?1:0;const result=await api(base(table.id)+'/topics'+(existing?'/'+existing.id:''),existing?'PATCH':'POST',{...body,...(existing?{version:existing.version}:{})});try{localStorage.removeItem(key)}catch{}location.hash='thread/'+table.id+'/'+(existing?.id||result.id)})}
 }
 const filesHtml=files=>files?.length?`<section class="campaign-attachments"><h3>${L('Attachments','Adjuntos')}</h3>${files.map(f=>`<a href="${H(f.url)}" target="_blank" rel="noopener">${f.content_type.startsWith('image/')?`<img src="${H(f.url)}" alt="${H(f.name)}" loading="lazy">`:'<span aria-hidden="true">▤</span>'}<span>${H(f.name)}<small>${(f.size/1024).toFixed(0)} KB ↗</small></span></a>`).join('')}</section>`:'';
 function uploadControl(type,parent){return `<label class="button campaign-upload">${type==='character'?L('Upload a portrait','Subir retrato'):L('Attach a file','Adjuntar archivo')}<input type="file" data-upload="${type}" data-parent="${parent}" accept="${type==='character'?'image/png,image/jpeg,image/webp':'image/png,image/jpeg,image/webp,application/pdf'}"></label><p class="campaign-fine">${type==='character'?L('PNG, JPEG or WebP, up to 5 MB.','PNG, JPEG o WebP, hasta 5 MB.'):L('Images up to 5 MB; PDF up to 10 MB. Attachments keep this page’s visibility.','Imágenes de hasta 5 MB; PDF de hasta 10 MB. Los adjuntos mantienen la visibilidad de esta página.')}</p><p data-upload-status role="status"></p>`}
 function bindUploads(onFile){document.querySelectorAll('[data-upload]').forEach(input=>input.onchange=async()=>{const file=input.files[0];if(!file)return;const statusEl=input.closest('section').querySelector('[data-upload-status]');input.disabled=true;try{const max=file.type==='application/pdf'?10*1024*1024:5*1024*1024;if(file.size>max){const e=Error();e.code='file_too_large';throw e}status(statusEl,L('Uploading…','Subiendo…'));const r=await fetch(base(table.id)+'/'+(({topic:'topics',reply:'replies',character:'characters'})[input.dataset.upload])+'/'+input.dataset.parent+'/files',{method:'POST',headers:{'x-kalvatar-request':'campaign-v1','content-type':file.type,'x-file-name':encodeURIComponent(file.name)},body:file,credentials:'same-origin'});const result=await r.json();if(!r.ok){const e=Error();e.code=result.error;throw e}await onFile(result.file)}catch(e){status(statusEl,errorText(e),true)}finally{input.disabled=false;input.value=''}})}
 async function revisionPanel(type,entity,container,afterRestore){const response=await api(base(table.id)+'/'+(type==='topic'?'topics':type==='reply'?'replies':'characters')+'/'+entity.id+'/history');container.innerHTML=`<h3>${L('Previous versions','Versiones anteriores')}</h3>${response.revisions.map((r,i)=>`<details><summary>${L('Version','Versión')} ${r.version} · ${H(r.editor_name)} · ${date(r.created_at)}</summary><div class="revision-preview">${type==='character'?`<h4>${H(r.snapshot.name)}</h4><p>${H(parseSheet(r.snapshot.sheet).story||'')}</p>`:`<h4>${H(r.snapshot.title||'')}</h4><p>${rich(r.snapshot.body||'')}</p>`}</div>${entity.can_edit&&!table.archived?`<button class="text-link" type="button" data-restore="${i}">${L('Restore as a new version','Restaurar como versión nueva')} ↺</button>`:''}</details>`).join('')||`<p>${L('There are no earlier versions yet.','Todavía no hay versiones anteriores.')}</p>`}`;container.querySelectorAll('[data-restore]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const old=response.revisions[Number(b.dataset.restore)].snapshot;let body=type==='character'?{name:old.name,sheet:parseSheet(old.sheet),portrait_id:old.portrait_id,archived:old.archived}:type==='topic'?{title:old.title,body:old.body,session:old.session,archived:old.archived,...(entity.author_id===session.user.id?{visibility:old.visibility}:{})}:{body:old.body,archived:old.archived};await api(base(table.id)+'/'+(type==='topic'?'topics':type==='reply'?'replies':'characters')+'/'+entity.id,'PATCH',{...body,version:entity.version});await afterRestore()}catch(e){toast(errorText(e));b.disabled=false}})}
 const parseSheet=s=>{if(typeof s==='object'&&s)return s;try{return JSON.parse(s)}catch{return {}}};
 async function threadPage(id,edit=false){const response=await api(base(table.id)+'/topics/'+id),t=response.topic;if(t.body.startsWith('{"format":"kalvatar-guide-v1"')&&!edit){location.hash='table/'+table.id+'/guide/'+id;return}if(edit){if(!t.can_edit){const e=Error();e.code='author_only';throw e}return editor(null,t)}const files=response.files,posts=response.replies;tablePage(t.title,L('A page from your campaign journal.','Una página de la bitácora de tu campaña.'),`<article class="campaign-paper"><header><span class="visibility-badge">${H(tag(t.visibility))}</span><p class="campaign-byline">${H(t.author_name)} · ${date(t.created_at)}${t.session?' · '+H(t.session):''}${t.version>1?' · '+L('version','versión')+' '+t.version:''}</p><div class="campaign-actions">${t.can_edit&&!table.archived?`<a class="text-link" href="#thread/${table.id}/${id}/edit">${L('Edit','Editar')} ✎</a><button type="button" class="text-link" id="archive-topic">${t.archived?L('Restore page','Restaurar página'):L('Archive page','Archivar página')}</button>`:''}<button type="button" class="text-link" id="topic-history">${L('History','Historial')}</button><button type="button" class="text-link" id="export-topic">${L('Export page','Exportar página')}</button></div></header><div class="campaign-rich">${rich(t.body)}</div>${filesHtml(files)}${t.can_edit&&!table.archived?`<section class="attachment-upload">${uploadControl('topic',id)}</section>`:''}<div id="topic-history-panel" class="campaign-history"></div></article><section class="forum-replies"><div class="campaign-toolbar"><h2>${L('Around the table','Alrededor de la mesa')}</h2><button type="button" class="text-link" id="thread-refresh">${L('Refresh replies','Actualizar respuestas')} ↻</button></div>${posts.map(p=>`<article class="forum-reply ${p.archived?'archived':''}" id="reply-${p.id}"><header><strong>${H(p.author_name)}</strong><span>${date(p.created_at)}</span></header><div class="campaign-rich">${p.archived?`<em>${L('Archived reply','Respuesta archivada')}</em>`:rich(p.body)}</div>${p.archived?'':filesHtml(p.files)}${p.can_edit&&!p.archived&&!t.archived&&!table.archived?`<section class="attachment-upload">${uploadControl('reply',p.id)}</section>`:''}${p.can_edit&&!table.archived?`<div class="campaign-actions"><button class="text-link" type="button" data-edit-reply="${p.id}">${L('Edit','Editar')}</button><button class="text-link" type="button" data-archive-reply="${p.id}">${p.archived?L('Restore','Restaurar'):L('Archive','Archivar')}</button><button class="text-link" type="button" data-reply-history="${p.id}">${L('History','Historial')}</button></div>`:''}<div class="reply-editor-slot"></div><div class="campaign-history"></div></article>`).join('')||`<p>${L('The first reply is still to come.','La primera respuesta está por llegar.')}</p>`}${!t.archived&&!table.archived?`<form id="reply-form" class="campaign-panel"><h3>${L('Add your voice','Suma tu voz')}</h3>${mentionEditor('body','',20000)}${formStatus()}<button type="submit" class="button">${L('Post reply','Publicar respuesta')} →</button></form>`:`<p class="campaign-archived-note">${L('This page is archived.','Esta página está archivada.')}</p>`}</section>`,t.kind==='thread'?'board':t.visibility==='dm'?'dm':'notes');$('#thread-refresh').onclick=()=>refresh();$('#export-topic').onclick=()=>download('kalvatar-note.json',{format:'kalvatar-note',version:1,title:t.title,body:t.body,session:t.session,visibility:t.visibility,replies:posts.map(p=>({author:p.author_name,body:p.body,created_at:p.created_at}))});$('#topic-history').onclick=async()=>{try{await revisionPanel('topic',t,$('#topic-history-panel'),refresh)}catch(e){toast(errorText(e))}};if($('#archive-topic'))$('#archive-topic').onclick=async()=>{try{await api(base(table.id)+'/topics/'+id,'PATCH',{version:t.version,archived:t.archived?0:1});refresh()}catch(e){toast(errorText(e))}};const form=$('#reply-form');if(form){mentions(form);const key=draftKey('reply',id);drafts(form,key,0);form.onsubmit=e=>{e.preventDefault();submit(form,async()=>{await api(base(table.id)+'/topics/'+id+'/replies','POST',{body:new FormData(form).get('body')});try{localStorage.removeItem(key)}catch{}refresh()})}}
  document.querySelectorAll('[data-edit-reply]').forEach(b=>b.onclick=()=>{const p=posts.find(p=>p.id===b.dataset.editReply),slot=$('#reply-'+p.id+' .reply-editor-slot');slot.innerHTML=`<form>${mentionEditor('body',p.body,20000)}${formStatus()}<button class="button" type="submit">${L('Save reply','Guardar respuesta')}</button></form>`;const f=slot.querySelector('form');mentions(f);f.onsubmit=e=>{e.preventDefault();submit(f,async()=>{await api(base(table.id)+'/replies/'+p.id,'PATCH',{version:p.version,body:new FormData(f).get('body')});refresh()})}});
  document.querySelectorAll('[data-archive-reply]').forEach(b=>b.onclick=async()=>{const p=posts.find(p=>p.id===b.dataset.archiveReply);try{await api(base(table.id)+'/replies/'+p.id,'PATCH',{version:p.version,archived:p.archived?0:1});refresh()}catch(e){toast(errorText(e))}});
  document.querySelectorAll('[data-reply-history]').forEach(b=>b.onclick=async()=>{const p=posts.find(p=>p.id===b.dataset.replyHistory);try{await revisionPanel('reply',p,$('#reply-'+p.id+' .campaign-history'),refresh)}catch(e){toast(errorText(e))}});bindUploads(async()=>refresh());
 }
 const sheetFields=[['manual_summary',()=>L('Manual values','Valores manuales')],['subclass',()=>L('Subclass','Subclase')],['rules_source',()=>L('Rules source','Fuente de reglas')],['attacks',()=>L('Attacks','Ataques')],['proficiencies',()=>L('Proficiencies','Competencias')],['senses',()=>L('Senses','Sentidos')],['resistances',()=>L('Resistances and immunities','Resistencias e inmunidades')],['notes',()=>L('Notes','Notas')],['class',()=>L('Class / vocation','Clase / vocación')],['background',()=>L('Background','Trasfondo')],['heritage',()=>L('Heritage feat','Dote de herencia')],['pronouns',()=>L('Pronouns','Pronombres')],['appearance',()=>L('Appearance','Apariencia')],['story',()=>L('Story','Historia')],['goals',()=>L('Goals & bonds','Objetivos y vínculos')],['traits',()=>L('Personality','Personalidad')],['abilities',()=>L('Ability scores','Características')],['combat',()=>L('HP, defenses & movement','PV, defensas y movimiento')],['skills',()=>L('Skills & proficiencies','Habilidades y competencias')],['equipment',()=>L('Equipment & attacks','Equipo y ataques')],['features',()=>L('Features & abilities','Rasgos y capacidades')],['spells',()=>L('Spells & resources','Conjuros y recursos')],['languages',()=>L('Languages','Idiomas')],['currency',()=>L('Coins','Monedas')]];
 async function characterList(){characters=(await api(base(table.id)+'/characters')).characters;tablePage(L('The company','La compañía'),L('The people who share this voyage. Everyone can read these sheets; each player and the DM can edit their own permitted characters.','Quienes comparten este viaje. La mesa puede leer las fichas; cada jugador edita sus personajes y el DM puede ayudar.'),`<div class="campaign-toolbar"><a class="button" href="#character-select/${table.id}">${L('Bring or create a character','Llevar o crear personaje')} +</a><label class="button campaign-upload">${L('Import character JSON','Importar personaje JSON')}<input id="import-character" type="file" accept="application/json,.json"></label></div><p id="character-import-status" role="status"></p><div class="character-grid">${characters.map(ch=>`<a href="#character-sheet/${table.id}/${ch.id}" class="character-card ${ch.archived?'archived':''}">${ch.portrait_id?`<img src="${base(table.id)+'/files/'+ch.portrait_id}" alt="" loading="lazy">`:`<span class="character-sigil" aria-hidden="true">${icon('leaf')}</span>`}<div><p class="eyebrow">${H(ch.owner_name)}${ch.archived?' · '+L('ARCHIVED','ARCHIVADO'):''}</p><h3>${H(ch.name)}</h3><p>${H(byId[ch.sheet.people]?.title||ch.sheet.ancestry_name||'')} · ${L('Level','Nivel')} ${ch.sheet.level||1}</p><p>${H(ch.sheet.class||'')}</p></div></a>`).join('')||`<div class="campaign-empty"><p>${L('The company is still gathering.','La compañía todavía se está reuniendo.')}</p></div>`}</div>`,'characters');$('#import-character').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>400000)throw Error();const data=JSON.parse(await file.text());if(data.format!=='kalvatar-character'||data.version!==1||!data.character?.name||!data.character.sheet){const err=Error();err.code='invalid_character';throw err}const result=await api(base(table.id)+'/characters','POST',{name:data.character.name,sheet:data.character.sheet});location.hash='character-sheet/'+table.id+'/'+result.id}catch(error){status($('#character-import-status'),errorText(error),true)}e.target.value=''}}
 async function characterEditor(ch=null){const s=ch?.sheet||{};tablePage(ch?L('Edit character','Editar personaje'):L('A new traveler','Un nuevo viajero'),L('Fill the sheet in your own words. These fields are editable; they do not calculate game rules.','Completa la ficha con tus palabras. Los campos son editables y no calculan reglas.'),`<form id="character-editor" class="campaign-panel">${s.builder?`<div class="builder-notice"><p>${L('Saving converts this campaign copy into a manual sheet for level advancement. Its guided version remains in history.','Guardar convierte esta copia de campaña en una ficha manual para subir de nivel. Su versión guiada queda en el historial.')}</p><label class="campaign-check-small"><input type="checkbox" required>${L('Use a manual sheet','Usar una ficha manual')}</label></div>`:''}${field('name',L('Character name','Nombre del personaje'),ch?.name||'','text','required maxlength="100"')}<div class="character-basic-grid"><label>${L('People','Pueblo')}<select name="people"><option value="">${L('Choose','Elige')}</option>${s.people&&!byId[s.people]?`<option value="${H(s.people)}" selected>${H(s.ancestry_name||s.people)}</option>`:''}${Pack2.data.tours.make_a_character.paths.map(p=>byId[p.people]).filter(Boolean).map(e=>`<option value="${e.id}" ${s.people===e.id?'selected':''}>${H(e.title)}</option>`).join('')}</select></label>${field('level',L('Level','Nivel'),s.level||1,'number','min="1" max="30" required')}</div><div class="character-fields">${sheetFields.map(([name,label],i)=>i<4?field(name,label(),s[name]||'','text','maxlength="10000"'):`<label>${label()}<textarea name="${name}" rows="${['story','equipment','features'].includes(name)?5:3}" maxlength="10000">${H(s[name]||'')}</textarea></label>`).join('')}</div>${formStatus()}<div class="campaign-actions"><button type="submit" class="button">${L('Save character online','Guardar personaje en línea')} →</button><a class="text-link" href="${ch?'#character-sheet/'+table.id+'/'+ch.id:'#table/'+table.id+'/characters'}">${L('Back','Volver')}</a></div></form>`,'characters');const form=$('#character-editor'),key=draftKey('character',ch?.id||'new');drafts(form,key,ch?.version||0);form.onsubmit=e=>{e.preventDefault();submit(form,async()=>{const f=new FormData(form),sheet={ruleset:s.ruleset||s.builder?.ruleset||'2014',people:f.get('people'),level:Number(f.get('level')),...Object.fromEntries(sheetFields.map(([k])=>[k,f.get(k)||'']))};const result=await api(base(table.id)+'/characters'+(ch?'/'+ch.id:''),ch?'PATCH':'POST',{name:f.get('name'),sheet,...(ch?{version:ch.version}:{})});try{localStorage.removeItem(key)}catch{}location.hash='character-sheet/'+table.id+'/'+(ch?.id||result.id)})}}
 async function characterPage(id,edit){const response=await api(base(table.id)+'/characters/'+id),ch=response.character,s=ch.sheet;if(edit){if(!ch.can_edit){const e=Error();e.code='author_only';throw e}location.hash='manual-character/campaign/'+table.id+'/'+id;return}tablePage(ch.name,L('A character of this company.','Un personaje de esta compañía.'),`<article id="print-character" class="campaign-paper character-sheet"><header class="character-sheet-header">${ch.portrait_id?`<img class="character-portrait" src="${base(table.id)+'/files/'+ch.portrait_id}" alt="${H(ch.name)}">`:''}<div><p class="eyebrow">${H(table.name)}</p><h2>${H(ch.name)}</h2><p>${(byId[s.people]?makeLink(s.people):H(s.ancestry_name||s.people))} · ${s.ruleset==='2024'?'2024':'Legacy (2014)'} · ${L('Level','Nivel')} ${s.level||1}</p><p>${H(s.class||'')}</p><p class="campaign-byline">${H(ch.owner_name)} · ${L('version','versión')} ${ch.version}</p></div></header><div class="campaign-actions no-print">${ch.can_edit&&!table.archived?`${s.builder?`<a class="button" href="#advance-character/${table.id}/${id}">${L('Level up / guided choices','Subir de nivel / elecciones guiadas')} ↗</a>`:''}<a class="text-link" href="#manual-character/campaign/${table.id}/${id}">${L('Edit sheet','Editar ficha')} ✎</a><button class="text-link" id="archive-character">${ch.archived?L('Restore character','Restaurar personaje'):L('Archive character','Archivar personaje')}</button>`:''}${ch.owner_id===session.user.id?`<button class="text-link" id="character-to-library">${L('Copy to my character library','Copiar a mis personajes')}</button>`:''}<button class="text-link" id="character-export">${L('Export JSON','Exportar JSON')}</button><button class="text-link" id="character-print">${L('Print / PDF','Imprimir / PDF')}</button><button class="text-link" id="character-history">${L('History','Historial')}</button></div>${s.builderReview&&s.builderReview!=='ready'?`<p class="builder-notice">${s.builderReview==='manual-review'?L('Manual racial rules: review their effects with the DM.','Reglas raciales manuales: revisa sus efectos con el DM.'):L('Draft: some creator choices remain pending.','Borrador: quedan elecciones pendientes en el creador.')}</p>`:''}<div id="campaign-character-play" class="no-print"></div><dl class="character-details">${sheetFields.filter(([key])=>key!=='class'&&s[key]).map(([key,label])=>`<div><dt>${label()}</dt><dd>${rich(s[key])}</dd></div>`).join('')}</dl></article>${ch.can_edit&&!table.archived?`<section class="campaign-panel attachment-upload no-print"><h3>${L('Character portrait','Retrato del personaje')}</h3>${uploadControl('character',id)}</section>`:''}<div id="character-history-panel" class="campaign-history"></div>`,'characters');if($('#character-to-library'))$('#character-to-library').onclick=async()=>{try{const result=await api('/api/my-characters/from-campaign','POST',{campaign_id:table.id,character_id:id});location.hash='my-character/'+result.id}catch(e){toast(errorText(e))}};import('./character-play.mjs?v=22').then(m=>m.mountPlay({target:'#campaign-character-play',sheet:s,editable:ch.can_edit&&!table.archived&&!ch.archived,language:Pack2.language,onSave:async play=>{const r=await api(base(table.id)+'/characters/'+id,'PATCH',{version:ch.version,sheet:{...s,play}});ch.version=r.character.version;Object.assign(s,r.character.sheet)}}));$('#character-export').onclick=()=>download('kalvatar-character.json',{format:'kalvatar-character',version:1,exported_at:new Date().toISOString(),character:{name:ch.name,sheet:s}});$('#character-print').onclick=()=>{document.body.classList.add('printing-character');window.print()};window.addEventListener('afterprint',()=>document.body.classList.remove('printing-character'),{once:true});$('#character-history').onclick=async()=>{try{await revisionPanel('character',ch,$('#character-history-panel'),refresh)}catch(e){toast(errorText(e))}};if($('#archive-character'))$('#archive-character').onclick=async()=>{try{await api(base(table.id)+'/characters/'+id,'PATCH',{version:ch.version,archived:ch.archived?0:1});refresh()}catch(e){toast(errorText(e))}};bindUploads(async file=>{await api(base(table.id)+'/characters/'+id,'PATCH',{version:ch.version,portrait_id:file.id});refresh()})}
 async function memberPage(){if(!isDm()){const e=Error();e.code='dm_only';throw e}const {invitations}=await api(base(table.id)+'/invitations');tablePage(L('Around your table','Alrededor de tu mesa'),L('Invite players, manage access, and keep the company together.','Invita jugadores, gestiona el acceso y reúne a la compañía.'),`<section class="campaign-panel"><h2>${L('Members','Miembros')}</h2><ul class="campaign-members">${members.map(m=>`<li><span><strong>${H(m.name)}</strong><small>${m.role==='dm'?'DM':L('Player','Jugador')}</small></span>${m.role!=='dm'?`<button class="text-link" data-remove-member="${H(m.user_id)}">${L('Remove access','Retirar acceso')}</button>`:''}</li>`).join('')}</ul></section><section class="campaign-panel"><h2>${L('A seat at the table','Un lugar en la mesa')}</h2><form id="invite-form"><div class="character-basic-grid">${field('days',L('Valid for days','Días de validez'),7,'number','min="1" max="30" required')}${field('max_uses',L('Player places','Cupos de jugadores'),20,'number','min="1" max="100" required')}</div>${formStatus()}<button type="submit" class="button">${L('Create invitation link','Crear enlace de invitación')} ↗</button></form><div id="invite-result" aria-live="polite"></div></section><section><h2>${L('Issued invitations','Invitaciones creadas')}</h2><div class="issued-invites">${invitations.map(i=>`<div><span>${i.uses} / ${i.max_uses} ${L('joined','se unieron')} · ${L('until','hasta')} ${date(i.expires_at)}${i.revoked?' · '+L('REVOKED','REVOCADA'):''}</span>${!i.revoked?`<button type="button" class="text-link" data-revoke="${i.id}">${L('Revoke','Revocar')}</button>`:''}</div>`).join('')}</div></section>`,'members');$('#invite-form').onsubmit=e=>{e.preventDefault();submit(e.currentTarget,async()=>{const f=new FormData(e.target),i=await api(base(table.id)+'/invitations','POST',{days:Number(f.get('days')),max_uses:Number(f.get('max_uses'))}),url=location.origin+location.pathname+'#join/'+i.token;$('#invite-result').innerHTML=`<label>${L('Share this link with your players','Comparte este enlace con tus jugadores')}<textarea id="invite-url" readonly rows="3">${H(url)}</textarea></label><button type="button" class="button" id="copy-invite">${L('Copy invitation','Copiar invitación')}</button>`;$('#copy-invite').onclick=async()=>{try{await navigator.clipboard.writeText(url);toast(L('Invitation copied.','Invitación copiada.'))}catch{$('#invite-url').select()}}})};document.querySelectorAll('[data-revoke]').forEach(b=>b.onclick=async()=>{try{await api(base(table.id)+'/invitations/'+b.dataset.revoke,'PATCH',{});refresh()}catch(e){toast(errorText(e))}});document.querySelectorAll('[data-remove-member]').forEach(b=>b.onclick=async()=>{try{await api(base(table.id)+'/members/'+b.dataset.removeMember,'PATCH',{active:0});refresh()}catch(e){toast(errorText(e))}})}
 async function joinPage(raw){await getSession();const info=await api('/api/invitations/'+raw);page(L('An invitation to the table.','Una invitación a la mesa.'),L('Your next voyage begins with good company.','Tu próximo viaje comienza con buena compañía.'),`<section class="campaign-welcome"><div class="campaign-welcome-mark" aria-hidden="true">${icon('compass')}</div><div><p class="eyebrow">${L('DM','DM')}: ${H(info.dm_name)}</p><h2>${H(info.name)}</h2><p>${H(info.description)}</p><p class="campaign-fine">${L('Invitation valid until','Invitación válida hasta')} ${date(info.expires_at)}</p>${session.user?`<form id="join-table"><p>${L('Join as','Entrar como')} <strong>${H(session.user.name)}</strong></p>${formStatus()}<button class="button" type="submit">${L('Take my place','Unirme a la mesa')} →</button></form>`:`<a class="button" target="_top" href="${H(session.sign_in)}">${L('Sign in and join','Iniciar sesión y unirme')} ↗</a>`}</div></section>`);if($('#join-table'))$('#join-table').onsubmit=e=>{e.preventDefault();submit(e.currentTarget,async()=>{const result=await api('/api/invitations/'+raw,'POST',{});location.hash='character-select/'+result.campaign_id})}}
 async function discoveries(){tablePage(L('The table’s chart','La carta de la mesa'),L('Every discovery opens another shore.','Cada descubrimiento abre otra orilla.'),`<div class="campaign-toolbar"><p>${table.unlocked.length} / ${entries.length} ${L('discovered entries','entradas descubiertas')}</p>${isDm()?`<a class="button" href="#table/${table.id}/chart">${L('Update discoveries','Actualizar descubrimientos')} →</a>`:''}</div><div class="entry-grid">${entries.filter(e=>table.unlocked.includes(e.id)).map(e=>articleCard(e,true)).join('')}</div>`,'discoveries')}
 async function chart(){if(!isDm()){const e=Error();e.code='dm_only';throw e}let selected=new Set(table.unlocked);tablePage(L('Chart the next discoveries','Traza los próximos descubrimientos'),L('Save once; every member receives the updated chart on their next visit.','Guarda una vez; toda la mesa recibirá la carta actualizada en su próxima visita.'),`<form id="online-chart" class="campaign-panel"><div class="campaign-toolbar"><label>${L('Find entries','Busca entradas')}<input id="online-chart-search" type="search"></label><label>${L('Category','Categoría')}<select id="online-chart-category"><option value="">${L('All entries','Todas las entradas')}</option>${visibleCategories().map(([id,c])=>`<option value="${id}">${H(Pack2.text(c.name))}</option>`).join('')}</select></label></div><div class="campaign-actions"><button type="button" class="text-link" id="discover-shown">${L('Discover shown entries','Descubrir las entradas mostradas')}</button><button type="button" class="text-link" id="hide-shown">${L('Hide shown entries','Ocultar las entradas mostradas')}</button><span id="online-chart-count" role="status"></span></div><div id="online-chart-list"></div>${formStatus()}<button type="submit" class="button">${L('Save the table’s chart','Guardar la carta de la mesa')} →</button></form>`,'discoveries');const list=()=>entries.filter(e=>(!$('#online-chart-category').value||e.category===$('#online-chart-category').value)&&matches(e,$('#online-chart-search').value)).sort((a,b)=>a.title.localeCompare(b.title));const draw=()=>{$('#online-chart-count').textContent=selected.size+' / '+entries.length;$('#online-chart-list').innerHTML=list().map(e=>`<label class="campaign-check"><input type="checkbox" data-discover="${e.id}" ${selected.has(e.id)?'checked':''}><span>${H(e.title)}<small>${H(e.region)}</small></span></label>`).join('')};$('#online-chart-search').oninput=draw;$('#online-chart-category').onchange=draw;$('#online-chart-list').onchange=e=>{const id=e.target.dataset.discover;if(id){e.target.checked?selected.add(id):selected.delete(id);$('#online-chart-count').textContent=selected.size+' / '+entries.length}};$('#discover-shown').onclick=()=>{list().forEach(e=>selected.add(e.id));draw()};$('#hide-shown').onclick=()=>{list().forEach(e=>selected.delete(e.id));draw()};$('#online-chart').onsubmit=e=>{e.preventDefault();submit(e.currentTarget,async()=>{await api(base(table.id),'PATCH',{version:table.version,unlocked:[...selected]});location.hash='table/'+table.id+'/discoveries'})};draw()}
 async function settings(){if(!isDm()){const e=Error();e.code='dm_only';throw e}tablePage(L('Keep your table','Cuida tu mesa'),L('Campaign details, an export, and a place to close the book between adventures.','Detalles de la campaña, una exportación y un lugar para cerrar el libro entre aventuras.'),`<form id="campaign-settings" class="campaign-panel">${field('name',L('Name','Nombre'),table.name,'text','required maxlength="100"')}<label>${L('Description','Descripción')}<textarea name="description" maxlength="3000" rows="4">${H(table.description)}</textarea></label>${formStatus()}<button class="button" type="submit">${L('Save details','Guardar detalles')}</button></form><section class="campaign-panel"><h2>${L('A copy of the journal','Una copia de la bitácora')}</h2><p>${L('The ZIP includes the pages your account can read, characters, revision history and attachment files. Other players’ private notes are excluded. A JSON-only export is also available.','El ZIP incluye las páginas que tu cuenta puede leer, personajes, historial y archivos adjuntos. Las notas privadas de otros jugadores quedan fuera. También puedes exportar solo el JSON.')}</p><a class="button" href="${base(table.id)+'/export-archive'}" download>${L('Download campaign ZIP','Descargar campaña ZIP')} ↓</a> <button class="text-link" type="button" id="export-campaign">${L('Export campaign JSON','Exportar campaña JSON')}</button></section><section class="campaign-panel"><h2>${table.archived?L('Open the book again','Abre el libro de nuevo'):L('Between voyages','Entre viajes')}</h2><p>${L('Archived campaigns remain readable and can be reopened.','Las campañas archivadas se pueden leer y reabrir.')}</p><button class="text-link" id="archive-campaign">${table.archived?L('Reopen campaign','Reabrir campaña'):L('Archive campaign','Archivar campaña')}</button></section>`,'settings');$('#campaign-settings').onsubmit=e=>{e.preventDefault();submit(e.currentTarget,async()=>{const f=new FormData(e.target);await api(base(table.id),'PATCH',{version:table.version,name:f.get('name'),description:f.get('description')});refresh()})};$('#export-campaign').onclick=async()=>{try{download('kalvatar-campaign.json',await api(base(table.id)+'/export'))}catch(e){toast(errorText(e))}};$('#archive-campaign').onclick=async()=>{try{await api(base(table.id),'PATCH',{version:table.version,archived:table.archived?0:1});refresh()}catch(e){toast(errorText(e))}}}
 async function soundtrack(){
  const songs=(await api(base(table.id)+'/music')).music;let editing=null;
  tablePage(L('The campaign soundtrack','La banda sonora de la campaña'),L('Keep tracks, playlists and atmospheres for your adventures. Each listener opens the link in their own music service.','Guarda pistas, playlists y ambientes para tus aventuras. Cada persona abre el enlace en su servicio de música.'),`<p class="campaign-fine">${L('Everyone can suggest music. The DM can feature one link for the session. Playback is personal and does not start automatically or synchronize between devices.','Todos pueden proponer música. El DM puede destacar un enlace para la sesión. La reproducción es personal: no comienza automáticamente ni se sincroniza entre dispositivos.')}</p>${!table.archived?`<details id="music-editor-details" class="campaign-panel"><summary>${L('Add music','Agregar música')} +</summary><form id="music-editor">${field('title',L('Title','Título'),'','text','required maxlength="160"')}${field('url',L('Track or playlist link','Enlace a la pista o playlist'),'','url','required maxlength="2000" placeholder="https://…"')}${field('scene',L('Scene, mood or session (optional)','Escena, ambiente o sesión (opcional)'),'','text','maxlength="120"')}<p class="campaign-fine">Spotify · YouTube · Apple Music · SoundCloud · Bandcamp</p>${formStatus()}<div class="campaign-actions"><button class="button" type="submit" id="music-save">${L('Save music link','Guardar enlace de música')}</button><button class="text-link" type="button" id="music-cancel" hidden>${L('Cancel edit','Cancelar edición')}</button></div></form></details>`:''}<div class="campaign-toolbar"><label class="campaign-search-label">${L('Find a title, scene or player','Busca un título, escena o jugador')}<input type="search" id="music-search"></label><button class="text-link" type="button" id="refresh-music">${L('Refresh','Actualizar')} ↻</button></div><label class="campaign-check-small"><input id="music-archived" type="checkbox">${L('Show archived','Mostrar archivados')}</label><div id="campaign-music-list" class="campaign-music-grid"></div><details class="campaign-panel atlas-music-suggestions"><summary>${L('Music from the atlas','Música sugerida en el atlas')}</summary><label>${L('Choose a region or power','Elige una región o poder')}<select id="atlas-music-region">${Object.keys(Pack2.data.music.regions).filter(id=>Pack2.canRead(id)).map(id=>`<option value="${id}">${H(byId[id]?.title||id)}</option>`).join('')}</select></label><div id="atlas-music-tracks"></div></details>`,'music');
  const draw=()=>{const q=fold($('#music-search').value),selected=songs.filter(s=>($('#music-archived').checked||!s.archived)&&fold(s.title+' '+s.scene+' '+s.author_name+' '+s.provider).includes(q));$('#campaign-music-list').innerHTML=selected.map(s=>`<article class="campaign-music-card ${s.featured?'featured':''} ${s.archived?'archived':''}"><p class="eyebrow">${s.featured?'✦ '+L('FEATURED BY THE DM','DESTACADA POR EL DM'):H(s.provider)}</p><h3><a href="${H(s.url)}" target="_blank" rel="noopener noreferrer">${H(s.title)} ↗</a></h3>${s.scene?`<p class="music-scene">${H(s.scene)}</p>`:''}<p class="campaign-fine">${H(s.author_name)} · ${H(new URL(s.url).hostname)}</p><div class="campaign-actions"><a class="text-link" href="${H(s.url)}" target="_blank" rel="noopener noreferrer">${L('Listen','Escuchar')} ↗</a>${!table.archived&&isDm()&&!s.archived?`<button type="button" class="text-link" data-feature-music="${s.id}">${s.featured?L('Unfeature','Quitar destacado'):L('Feature for the session','Destacar para la sesión')}</button>`:''}${!table.archived&&(isDm()||s.author_id===session.user.id)?`<button class="text-link" type="button" data-edit-music="${s.id}">${L('Edit','Editar')}</button><button class="text-link" type="button" data-archive-music="${s.id}">${s.archived?L('Restore','Restaurar'):L('Archive','Archivar')}</button>`:''}</div></article>`).join('')||`<div class="campaign-empty"><p>${L('The first song is still to come.','La primera canción está por llegar.')}</p></div>`;
   document.querySelectorAll('[data-feature-music]').forEach(b=>b.onclick=async()=>{const s=songs.find(s=>s.id===b.dataset.featureMusic);try{await api(base(table.id)+'/music/'+s.id,'PATCH',{version:s.version,featured:s.featured?0:1});refresh()}catch(e){toast(errorText(e))}});
   document.querySelectorAll('[data-archive-music]').forEach(b=>b.onclick=async()=>{const s=songs.find(s=>s.id===b.dataset.archiveMusic);try{await api(base(table.id)+'/music/'+s.id,'PATCH',{version:s.version,archived:s.archived?0:1});refresh()}catch(e){toast(errorText(e))}});
   document.querySelectorAll('[data-edit-music]').forEach(b=>b.onclick=()=>{editing=songs.find(s=>s.id===b.dataset.editMusic);const form=$('#music-editor');for(const name of ['title','url','scene'])form.elements.namedItem(name).value=editing[name];$('#music-editor-details').open=true;$('#music-save').textContent=L('Save changes','Guardar cambios');$('#music-cancel').hidden=false;form.querySelector('input').focus()});
  };
  $('#music-search').oninput=draw;$('#music-archived').onchange=draw;$('#refresh-music').onclick=()=>refresh();draw();
  const form=$('#music-editor');if(form){form.onsubmit=e=>{e.preventDefault();submit(form,async()=>{const f=new FormData(form);await api(base(table.id)+'/music'+(editing?'/'+editing.id:''),editing?'PATCH':'POST',{title:f.get('title'),url:f.get('url'),scene:f.get('scene'),...(editing?{version:editing.version}:{})});refresh()})};$('#music-cancel').onclick=()=>{editing=null;form.reset();$('#music-save').textContent=L('Save music link','Guardar enlace de música');$('#music-cancel').hidden=true}};
  const suggestions=()=>{const tracks=Pack2.data.music.regions[$('#atlas-music-region').value]||[];$('#atlas-music-tracks').innerHTML=tracks.map(t=>{const q=encodeURIComponent(t.title+' '+t.from);return `<article class="atlas-music-track"><h3>${H(t.title)}</h3><p>${H(t.from)}</p><div class="campaign-actions"><a class="text-link" target="_blank" rel="noopener noreferrer" href="https://open.spotify.com/search/${q}">Spotify ↗</a><a class="text-link" target="_blank" rel="noopener noreferrer" href="https://www.youtube.com/results?search_query=${q}">YouTube ↗</a></div></article>`}).join('')};$('#atlas-music-region').onchange=suggestions;suggestions();
 }
 async function profile(){if(!await signed())return;page(L('My profile','Mi perfil'),L('The name your table sees.','El nombre que ve tu mesa.'),account()+`<form id="profile-form" class="campaign-panel">${field('name',L('Display name','Nombre visible'),session.user.name,'text','required maxlength="80"')}<p class="campaign-fine">${H(session.user.email)}</p>${formStatus()}<button class="button" type="submit">${L('Save name','Guardar nombre')}</button></form>`);$('#profile-form').onsubmit=e=>{e.preventDefault();submit(e.currentTarget,async()=>{session.user=await api('/api/profile','PATCH',{name:new FormData(e.target).get('name')});toast(L('Name saved.','Nombre guardado.'));refresh()})}}
 async function dispatch(parts,ticket){if(parts[0]==='tables')return hub();if(parts[0]==='account')return profile();if(parts[0]==='join')return joinPage(parts[1]);if(!await signed())return;if(ticket!==serial)return;await openTable(parts[1]);if(ticket!==serial)return;if(parts[0]==='thread')return threadPage(parts[2],parts[3]==='edit');if(parts[0]==='character-sheet')return characterPage(parts[2],parts[3]==='edit');const tab=parts[2]||'board';if(['board','notes','dm'].includes(tab)){if(tab==='dm'&&!isDm()){const e=Error();e.code='dm_only';throw e}return topicList(tab)}if(tab==='new-dm'&&!isDm()){const e=Error();e.code='dm_only';throw e}if(['new-thread','new-note','new-dm'].includes(tab))return editor(tab,null,new URLSearchParams(location.hash.split('?')[1]||'').get('entry')?'[[entry:'+new URLSearchParams(location.hash.split('?')[1]).get('entry')+'|'+(byId[new URLSearchParams(location.hash.split('?')[1]).get('entry')]?.title||'')+']]\n':'');if(tab==='guide'){const mod=await import('/campaign-guide.mjs');return mod.mount({api,base,table,page:tablePage},parts[3],parts[4])}if(tab==='music')return soundtrack();if(tab==='characters')return characterList();if(tab==='new-character')return characterEditor();if(tab==='members')return memberPage();if(tab==='discoveries')return discoveries();if(tab==='chart')return chart();if(tab==='settings')return settings();const e=Error();e.code='not_found';throw e}
 function route(parts){const ticket=++serial;if(window.CharacterBook?.route(parts))return true;if(!['tables','table','thread','character-sheet','join','account'].includes(parts[0]))return false;loading();const normalized=parts.map(p=>p.split('?')[0]);dispatch(normalized,ticket).catch(e=>{if(ticket===serial&&e.code!=='route_changed')failPage(e)});return true}
 function refresh(){route(location.hash.slice(1).split('/'))}
 function nav(){window.CharacterBook?.nav();const root=$('.pack-nav');if(root&&!root.querySelector('[data-nav="tables"]'))root.insertAdjacentHTML('afterbegin',`<a data-nav="tables" href="#tables"><span class="nav-icon" aria-hidden="true">⚑</span>${L('My campaigns','Mis campañas')}</a>`);let button=$('#campaign-hub');if(!button){$('.topbar-right').insertAdjacentHTML('afterbegin',`<a id="campaign-hub" class="campaign-hub-link" href="#tables" aria-label="${L('My campaigns','Mis campañas')}"><span aria-hidden="true">⚑</span><span class="campaign-hub-label">${L('My campaigns','Mis campañas')}</span></a>`)}else{button.setAttribute('aria-label',L('My campaigns','Mis campañas'));button.querySelector('.campaign-hub-label').textContent=L('My campaigns','Mis campañas')}if(!booted){booted=true;getSession().catch(()=>{})}}
 function articlePanel(e){return `<section class="table-notes online-entry-notes" data-online-entry="${e.id}"><p class="eyebrow">${L('YOUR CAMPAIGN JOURNAL','LA BITÁCORA DE TU CAMPAÑA')}</p><h2>${H(Pack2.campaign.name)}</h2><div id="online-entry-links"><p>${L('Opening the journal…','Abriendo la bitácora…')}</p></div></section>`}
 function afterRoute(){if(!location.hash.startsWith('#entry/')||!Pack2.campaign?.server)return;const entry=location.hash.slice(7),c=Pack2.campaign.id;api(base(c)+'/entry-notes/'+entry).then(result=>{const el=$('#online-entry-links');if(!el||el.closest('[data-online-entry]')?.dataset.onlineEntry!==entry)return;el.innerHTML=`<div class="campaign-actions"><a class="button" href="#table/${c}/new-note?entry=${encodeURIComponent(entry)}">${L('A private note on this entry','Una nota privada sobre esta entrada')} +</a><a class="text-link" href="#table/${c}/board">${L('Open the table forum','Abrir el foro de la mesa')} →</a></div>${result.topics.length?`<ul class="entry-backlinks">${result.topics.map(t=>`<li><a href="#thread/${c}/${t.id}">${H(t.title)}</a><span>${H(tag(t.visibility))}</span></li>`).join('')}</ul>`:`<p>${L('No campaign pages mention this entry yet.','Todavía no hay páginas de campaña que mencionen esta entrada.')}</p>`}`}).catch(e=>{const el=$('#online-entry-links');if(el)el.innerHTML=`<p>${H(errorText(e))}</p><a class="text-link" href="#tables">${L('My campaigns','Mis campañas')} →</a>`})}
 document.addEventListener('click',e=>{if(e.target.closest('[data-signout]'))Pack2.clearServer();if(e.target.closest('[data-leave-reading]')){Pack2.clearServer();location.hash='browse'}});
 document.addEventListener('kalvatar-language',()=>nav());
 return {route,nav,afterRoute,articlePanel,rich,refresh,get current(){return table}};
})();
